'use strict';

const CACHE_VERSION = "v2";
const CACHE = 'azan-' + CACHE_VERSION;
const PRECACHE = [
  "/",
  "/assets/index-yLYqV6Xc.css",
  "/assets/index-DvVK0Q-I.js",
  "/manifest.webmanifest",
  "/robots.txt",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/icon-maskable-512.png",
  "/icons/apple-touch-icon.png",
  "/patterns/zellige.svg",
  "/audio/chime-calm.wav",
  "/audio/chime-dawn.wav",
  "/audio/chime-alert.wav",
  "/audio/adhan/adhan-cc0.mp3",
  "/fonts/tajawal-arabic-400.woff2",
  "/fonts/tajawal-arabic-500.woff2",
  "/fonts/tajawal-arabic-700.woff2",
  "/fonts/ibm-plex-sans-latin.woff2",
  "/fonts/licenses/OFL-Tajawal.txt",
  "/fonts/licenses/OFL-IBM-Plex-Sans.txt"
];
const NAVIGATION_FALLBACK = '/index.html';

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // Cache each entry independently: one missing icon must not abort the whole
    // installation and leave the app with no offline shell at all.
    await Promise.all(PRECACHE.map((url) =>
      cache.add(new Request(url, { cache: 'reload' })).catch(() => undefined)
    ));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter((name) => name !== CACHE).map((name) => caches.delete(name)));

    // Drop hashed bundles left by earlier builds. The cache used to keep them
    // forever: every deploy added a ~160 KiB gzip copy of the app and nothing
    // removed it. Only entries under /assets/ that are missing from this build's
    // manifest are deleted; the app has no dynamic import, so no open page needs
    // an old hash.
    const cache = await caches.open(CACHE);
    const keep = new Set(PRECACHE);
    const stale = (await cache.keys()).filter((request) => {
      const path = new URL(request.url).pathname;
      return path.startsWith('/assets/') && !keep.has(path);
    });
    await Promise.all(stale.map((request) => cache.delete(request)));

    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  const data = event.data || {};
  if (data.type === 'SKIP_WAITING') self.skipWaiting();
});

/** Only same-origin GETs are ours; everything else goes straight to the network. */
function isOurs(request) {
  if (request.method !== 'GET') return false;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return false;
  if (url.pathname === '/sw.js') return false;
  return true;
}

async function networkFirstNavigation(request) {
  const cache = await caches.open(CACHE);
  const cached = (await cache.match(NAVIGATION_FALLBACK)) || (await cache.match('/'));
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 4000);
  try {
    const fresh = await fetch(request, { signal: controller.signal, cache: 'no-cache' });
    clearTimeout(timer);
    if (fresh && fresh.ok) {
      await cache.put(NAVIGATION_FALLBACK, fresh.clone());
      return fresh;
    }
    // A captive portal or a proxy error answers with a page that is not the app.
    // If we have a shell, prefer it over showing someone else's error page.
    if (cached) return cached;
    return fresh;
  } catch (error) {
    clearTimeout(timer);
    if (cached) return cached;
    return new Response('Azan Global is offline and the shell is not cached yet.', {
      status: 503,
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    });
  }
}

async function cacheFirst(request) {
  const cache = await caches.open(CACHE);
  const cached = await cache.match(request);
  if (cached) return cached;
  try {
    const fresh = await fetch(request);
    if (fresh && fresh.ok) await cache.put(request, fresh.clone());
    return fresh;
  } catch (error) {
    return Response.error();
  }
}

async function staleWhileRevalidate(event) {
  const request = event.request;
  const cache = await caches.open(CACHE);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((fresh) => {
      if (fresh && fresh.ok) return cache.put(request, fresh.clone()).then(() => fresh);
      return fresh;
    })
    .catch(() => null);

  if (cached) {
    event.waitUntil(network);
    return cached;
  }
  const fresh = await network;
  return fresh || Response.error();
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (!isOurs(request)) return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstNavigation(request));
    return;
  }

  // Media elements may send a Range header; the Cache API cannot answer a 206
  // from a full body, so let those requests through untouched.
  if (request.headers.has('range')) return;

  const url = new URL(request.url);
  if (url.pathname.startsWith('/audio/')) {
    event.respondWith(cacheFirst(request));
    return;
  }

  // Generated geographic catalogue: one file per Moroccan region, plus the
  // light index. Cache-first keeps a downloaded region usable offline and avoids
  // re-downloading megabytes on every visit.
  if (url.pathname.startsWith('/data/cities/')) {
    event.respondWith(cacheFirst(request));
    return;
  }

  event.respondWith(staleWhileRevalidate(event));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const payload = event.notification.data || {};
  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const sameOrigin = windows.find((client) => new URL(client.url).origin === self.location.origin);
    if (sameOrigin) {
      await sameOrigin.focus();
      sameOrigin.postMessage({ type: 'azan:notification-click', data: payload });
      return;
    }
    await self.clients.openWindow('/#/home');
  })());
});
